                agg.reasons
                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
                changed = true;
            }
        }
    }
    changed
}

pub(crate) fn union_linked(
    agg: &mut Aggregation,
    groups: &GroupTable,
    base_versions: &BTreeMap<PackageId, Version>,
