        &commits,
    );
    let pkg_a = PackageId::parse("pkg-a").unwrap();
    assert_eq!(agg.severities().get(&pkg_a), Some(&Severity::Major));
    assert!(matches!(
        agg.reasons().get(&pkg_a),
        Some(BumpReason::Inference { commits: 1, .. })
    ));
}

