/// A linked group behaves like a fixed one here: the fresh member lifts the retained member's group to its severity.
#[test]
fn test_pre_mode_fresh_linked_member_releases_at_the_retained_severity() {
    let agg = aggregate_pre_cycle(
        &["pkg-a", "pkg-b"],
        &[
            ("breaking", "---\npkg-a: major\n---\n\nBreaks.\n"),
            ("small-fix", "---\npkg-b: patch\n---\n\nFixes.\n"),
        ],
        &["breaking"],
        Some(GroupKind::Linked),
        &crate::infer::NoInference,
    );
    let pkg_b = PackageId::parse("pkg-b").unwrap();
    let severities = agg.severities();
    assert_eq!(severities.get(&PackageId::parse("pkg-a").unwrap()), Some(&Severity::Major));
    assert_eq!(severities.get(&pkg_b), Some(&Severity::Major));
    assert!(
        matches!(agg.reasons().get(&pkg_b), Some(BumpReason::Changeset { changesets }) if changesets == &["small-fix"]),
        "the fresh changeset, not the recorded one, explains the release: {:?}",
        agg.reasons().get(&pkg_b)
    );
}

