edits = {
    "docs/architecture/wire-compat.md": [(
        "- The decision digest covers the sorted consumed changesets (version 3 only) and the sorted entries (package, target version, reasons), not the schema version, so decisions of any version with the same entries and no consumed changesets share a digest. The digest is verified on every read.",
        "- The decision digest covers the sorted entries (package, target version, reasons) and, for version 3, the count and sorted list of consumed changesets. Versions 1 and 2 with the same entries share a digest; a version 3 decision never shares one with them. A version 3 list that is not sorted and free of duplicates fails to decode. The digest is verified on every read.",
    )],
    "docs/releasing.md": [(
        "If a stale release PR was merged anyway, the release fails with [E165](errors.md) because the changesets the merge deleted are not the ones its decision recorded, and every later push to `main` retries it.",
        "If a stale release PR whose changesets were already consumed on `main` was merged anyway, the release fails with [E165](errors.md) because the changesets the merge deleted are not the ones its decision recorded, and every later push to `main` retries it. A stale PR that releases only bumps inferred from commits deletes no changesets, so E165 does not catch it: keep `Hold release PR` enabled, which keeps a stale PR in draft.",
    )],
}
for path, pairs in edits.items():
    s = open(path).read()
    for old, new in pairs:
        assert s.count(old) == 1, (path, old[:40])
        s = s.replace(old, new)
    open(path, "w").write(s)

